function updateMetrics(){if(!result)return;const cards=[...document.querySelectorAll('.metrics article')];const staticValues=[(result.maxDisplacement*1000).toFixed(2),(Math.max(...result.supportForces.map(v=>Math.hypot(...v)))/1000).toFixed(2),result.frequency[0].toFixed(2)];for(let i=0;i<3;i++){const modal=view!=='static'&&view!=='decay';cards[i].querySelector('span').textContent=modal?(lang==='zh'?['一阶固有频率','二阶固有频率','三阶固有频率'][i]:['First natural frequency','Second natural frequency','Third natural frequency'][i]):t(['displacement','reaction','frequency'][i]);cards[i].querySelector('strong').textContent=modal?result.frequency[i].toFixed(2):staticValues[i];cards[i].querySelector('strong').style.color=modal&&+view===i?'var(--accent)':'';cards[i].querySelector('small').textContent=modal?'Hz':['mm','kN','Hz'][i];}if(view==='decay'&&result.dynamics){const d=result.dynamics;cards[0].querySelector('span').textContent=t('peakForce');cards[0].querySelector('strong').textContent=(d.peakForce/1000).toFixed(3);cards[0].querySelector('small').textContent='kN';cards[1].querySelector('span').textContent=t('energyLeft');cards[1].querySelector('strong').textContent=(100*d.energy.at(-1)/d.initialEnergy).toFixed(1);cards[1].querySelector('small').textContent='%';} }
