function renderEditor(){if(!route.length)return;selected=Math.min(selected,route.length-1);station=Math.min(station,route.length);const c=route[selected];$('segments').replaceChildren(...route.map((r,i)=>{let b=document.createElement('button');b.textContent=`${i+1} ${r.kind==='straight'?'━':'╰'}`;b.className=i===selected?'active':'';b.title=`${t('component')} ${i+1}`;b.onclick=()=>{selected=i;renderEditor();highlight();};return b;}));$('selected-label').textContent=`${t('component')} ${selected+1}`;$('dimension-label').textContent=t(c.kind==='straight'?'length':'radius');$('dimension').replaceChildren(...(c.kind==='straight'?[3,5,8]:[1.5,2,3]).map(r=>new Option(`${Math.round(r*diameter*1000)} mm`,r)));$('dimension').value=c.ratio;$('roll-field').hidden=c.kind!=='elbow';$('roll').value=c.roll;$('remove').disabled=route.length===1;$('station').replaceChildren(...Array.from({length:route.length+1},(_,i)=>new Option(i===0?t('inlet'):`${t('joint')} ${i}${i===route.length?' · '+t('endpoint'):''}`,i)));$('station').value=station;$('support').disabled=station===0;$('support').value=station===0?'fixed':supports[station]?.type||'none';$('spring-field').hidden=$('support').value!=='spring';$('spring').value=Math.log10((supports[station]?.k||100000)/1000);$('spring-value').textContent=`${Math.round(10**+$('spring').value)} kN/m`;[...$('wall').options].forEach(o=>o.textContent=`${+(diameter*+o.value*1000).toFixed(1)} mm`);$('add-straight').disabled=$('add-elbow').disabled=route.length>=10;}
