async function calculate(){const id=++requestId;$('status').textContent=t('loadingData');try{const design=getDesign(),snapshot=design.route;
 const loaded=await Promise.all(snapshot.map(r=>loadComponent(r,design.diameter,design.wall)));if(id!==requestId)return;components=loaded;
 $('status').textContent=t('solving');const ss=[{node:0,fixed:[0,1,2,3,4,5]}];Object.entries(design.supports).forEach(([node,s])=>{if(+node>snapshot.length||+node===0)return;if(s.type==='fixed')ss.push({node:+node,fixed:[0,1,2,3,4,5]});if(s.type==='guide')ss.push({node:+node,fixed:[2]});if(s.type==='spring')ss.push({node:+node,spring:[0,0,s.k,0,0,0]});});
 solvedDesign=design;worker.postMessage({id,request:{components,rolls:snapshot.map(r=>r.roll*Math.PI/180),deltaT:design.temperature,gravity:design.gravity?[0,0,-9.81]:[0,0,0],supports:ss,...(view==='decay'?{dynamic:design.damper}:view==='forced'?{harmonic:{...design.excitation,damper:design.damper}}:{})}});
 }catch(e){if(id===requestId){$('status').textContent=t('error');console.error(e);}}}
async function loadComponent(r,d=diameter,w=wall){const entry=catalog.find(c=>c.kind===r.kind&&Math.abs(c.diameter-d)<1e-9&&Math.abs(c.thickness/d-w)<1e-9&&Math.abs((r.kind==='straight'?c.length:c.radius)/d-r.ratio)<1e-9);if(!entry)throw Error('COMPONENT');if(!cache.has(entry.id))cache.set(entry.id,fetch('./data/'+entry.file).then(r=>{if(!r.ok)throw Error('FETCH');return r.json();}).catch(e=>{cache.delete(entry.id);throw e;}));return cache.get(entry.id);}
worker.onmessage=({data})=>{if(data.id!==requestId)return;if(data.error){$('status').textContent=t('error');console.error(data.error);return;}result=data.result;pending=false;['baseline','review','save-project'].forEach(id=>$(id).disabled=false);dynamicTime=0;
 document.body.classList.remove('solving');$('mass').textContent=result.mass.toFixed(1);$('solve-time').textContent=`${Math.round(result.elapsedMs)} ms · ${route.length} ${lang==='zh'?'个组件':'components'}`;$('status').textContent=overlap(result.paths)?t('overlap'):journey?.task()!=='build'&&result.maxDisplacement>diameter*.15?t('large'):result.dynamics?.blocked?t('blockedDamper'):'';rebuild();syncExtras();updateSceneLabels();try{localStorage.setItem('agentfem-pipe-draft',JSON.stringify(projectEnvelope(solvedDesign)));}catch{}if(needsFit){fit();needsFit=false;}journey?.solved();};
