   const reference=dyn?result.paths[i].map((p,j)=>p.map((v,k)=>v+result.modeDisplacements[i][j][k][0]*dyn.coordinates[0][0]*Math.cos(2*Math.PI*dyn.frequency[0]*dynamicTime)*+$('scale').value)):view==='static'&&referenceCompatible()?baseline.result.paths[i].map((p,j)=>p.map((v,k)=>v+baseline.result.displacements[i][j][k]*+$('scale').value)):result.paths[i];
   ghosts[i].visible=journey?.task()!=='build';
