 if(result.dynamics){const d=result.dynamics;d.time.forEach((time,i)=>{for(const [key,values,unit] of [['undamped_displacement',d.reference,'m'],['damped_displacement',d.signal,'m'],['damper_force',d.force,'N'],['energy',d.energy,'J'],['dissipated_energy',d.dissipated,'J']])rows.push(['dynamic',key,key.includes('displacement')?'probe':d.node,time,values[i],unit]);});}
