updateMetrics=()=>{baseMetrics();if(view==='forced'&&result?.harmonic){const h=result.harmonic,cards=[...document.querySelectorAll('.metrics article')],values=[h.current.amplitude*1000,h.reference.amplitude*1000,h.damperForce/1000],labels=lang==='zh'?['加装后测点振幅','加装前测点振幅','阻尼器力幅值']:['Probe amplitude · added damper','Probe amplitude · no added damper','Damper force amplitude'];for(let i=0;i<3;i++){cards[i].querySelector('span').textContent=labels[i];cards[i].querySelector('strong').textContent=values[i].toFixed(3);cards[i].querySelector('small').textContent=i===2?'kN':'mm';}if(h.blocked)$('status').textContent=lang==='zh'?'施力方向已固定，该方向没有位移响应。':'The excitation direction is fixed; its displacement is zero.';}};
reportHTML=()=>(view==='forced'&&result?.harmonic?'':baseReport())+(view==='forced'&&result?.harmonic?`<h3>${lang==='zh'?'阻尼器减振对比':'Damper comparison'}</h3><p>F = ${result.harmonic.force} N · f = ${result.harmonic.frequency} Hz · ζ = ${result.harmonic.zeta*100}% · ${t('joint')} ${result.harmonic.node} / ${'XYZ'[result.harmonic.axis]}<br>${lang==='zh'?'测点振幅（无 / 有附加阻尼器）':'Probe amplitude (without / with added damper)'}: ${(result.harmonic.reference.amplitude*1000).toFixed(5)} / ${(result.harmonic.current.amplitude*1000).toFixed(5)} mm<br>${lang==='zh'?'阻尼器力幅值':'Damper force amplitude'}: ${(result.harmonic.damperForce/1000).toFixed(4)} kN<br>c = ${result.harmonic.damper.c} N·s/m · ${result.harmonic.modeCount} modes</p><p>${t('modelScope')}</p>`:'');
engineering=setupEngineering({getLanguage:()=>lang,getNodeCount:()=>route.length,getResult:()=>result,getExcitation:()=>excitation,setExcitation:p=>{undoStack.push(getDesign());redoStack.length=0;excitation=p;lastDesign=getDesign();},onChange:()=>schedule(),onThermal:()=>{view='static';playing=false;phase=Math.PI/1.4;updateSceneLabels();schedule();},onVibration:()=>{view='0';playing=!reduced;updateSceneLabels();},onForced:()=>{view='forced';playing=!reduced;phase=0;updateSceneLabels();schedule();}});
const baseTranslate=translate;translate=()=>{baseTranslate();engineering.sync();power?.sync();$('project-state').textContent='';$('about-copy').insertAdjacentHTML('beforeend',lang==='zh'?'<p><b>受迫振动</b><br>用户给定连接点简谐力；在 12 阶系统模态上求解复数动态刚度。背景模态阻尼比为用户假设，两条曲线使用相同值。扫频范围为一阶频率的 0.2–2 倍，共 161 点；离散峰值不等于精确共振峰。显示同一施力点、同一方向的峰值振幅，非 RMS。四大管道采用独立生成的研究截面组件，尺寸与材料假设见案例说明。内压、介质、保温重量、温度相关材料及支吊架预载仍待接入。</p>':'<p><b>Forced response</b><br>User-specified harmonic joint force; complex dynamic stiffness in 12 system modes. Both curves use the same assumed background modal damping. The sweep samples 161 points over 0.2–2 times the first natural frequency; sampled maxima are not exact resonance peaks. Peak (not RMS) amplitudes at the force joint/direction. Power-piping sections are independently generated research benchmarks; pressure, contents, insulation, temperature-dependent properties and hanger preload remain outside this release.</p>');};
