let chartStamp='';
function drawFrequencyResponse(){
 const h=result.harmonic,c=$('trace'),r=c.getBoundingClientRect();if(!r.width||!r.height)return;const stamp=[requestId,r.width,r.height,lang].join('|');if(stamp===chartStamp)return;chartStamp=stamp;
 const ratio=Math.min(devicePixelRatio,2);c.width=r.width*ratio;c.height=r.height*ratio;const ctx=c.getContext('2d');ctx.scale(ratio,ratio);
 const w=r.width,height=r.height,left=36,right=12,top=18,bottom=22,maximum=Math.max(1e-12,...h.sweep.flatMap(s=>[s.withDamper,s.withoutDamper])),lo=h.sweep[0].frequency,hi=h.sweep.at(-1).frequency,x=f=>left+(f-lo)/(hi-lo)*(w-left-right),y=a=>height-bottom-a/maximum*(height-top-bottom);
 ctx.font='9px sans-serif';ctx.fillStyle='#9fb8b1';ctx.fillText('mm',2,10);
 for(let i=0;i<=2;i++){const value=maximum*i/2;ctx.strokeStyle='#294240';ctx.beginPath();ctx.moveTo(left,y(value));ctx.lineTo(w-right,y(value));ctx.stroke();ctx.fillText((value*1000).toPrecision(2),0,y(value)+3);}
 for(let i=0;i<=2;i++){const f=lo+(hi-lo)*i/2;ctx.fillText(f.toFixed(1),x(f)-8,height-7);}ctx.fillText('Hz',w-15,10);
 for(const [key,color,dash] of [['withoutDamper','#a1b4b0',[3,3]],['withDamper','#80ded0',[]]]){ctx.strokeStyle=color;ctx.lineWidth=1.6;ctx.setLineDash(dash);ctx.beginPath();h.sweep.forEach((s,i)=>i?ctx.lineTo(x(s.frequency),y(s[key])):ctx.moveTo(x(s.frequency),y(s[key])));ctx.stroke();}
 ctx.setLineDash([]);if(h.frequency>=lo&&h.frequency<=hi){ctx.strokeStyle='#dbb67d';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x(h.frequency),top);ctx.lineTo(x(h.frequency),height-bottom);ctx.stroke();}
 $('trace-caption').textContent=lang==='zh'?'频率响应 · 峰值振幅':'Frequency response · peak amplitude';$('trace-clock').textContent=h.frequency.toFixed(2)+' Hz';
 $('trace-info').textContent=lang==='zh'?'虚线：未加阻尼器 · 实线：当前配置。点击曲线区域改变激励频率。':'Dashed: no damper · solid: current. Click the chart to change excitation frequency.';
}
