const annotationArrow=new THREE.ArrowHelper(new THREE.Vector3(0,0,1),new THREE.Vector3(),1,0xe3bd7a);scene.add(annotationArrow);annotationArrow.visible=false;
const callout=document.createElement('div');callout.id='scene-callout';$('viewport').append(callout);
function updateCallout(){
 if(!result||pending||!journey||journey.task()==='build'||view==='forced'){annotationArrow.visible=false;callout.hidden=true;return;}
 let start,delta,label;
 if(view==='static'){
  let peak=0,at=[0,0];result.displacements.forEach((path,i)=>path.forEach((v,j)=>{const mag=Math.hypot(...v);if(mag>peak){peak=mag;at=[i,j];}}));
  start=new THREE.Vector3(...result.paths[at[0]][at[1]]);delta=new THREE.Vector3(...result.displacements[at[0]][at[1]]).multiplyScalar(+$('scale').value);
  label=(lang==='zh'?'最大总位移 ':'Max. total movement ')+(peak*1000).toFixed(2)+' mm';
 }else if(view==='forced'&&result.harmonic){
  const h=result.harmonic;start=new THREE.Vector3(...result.nodes[h.node]);delta=new THREE.Vector3(...[0,1,2].map(k=>k===h.axis?-diameter*3:0));start.sub(delta);
  label=(lang==='zh'?'周期力 / 测点 ':'Force / probe ')+h.node+' · '+h.force+' N · '+h.frequency.toFixed(3)+' Hz';
 }else {annotationArrow.visible=false;callout.hidden=true;return;}
 const length=delta.length();annotationArrow.visible=length>1e-8;if(length>1e-8){annotationArrow.position.copy(start);annotationArrow.setDirection(delta.clone().normalize());annotationArrow.setLength(length,Math.min(diameter*.6,length*.25),Math.min(diameter*.25,length*.12));}
 const end=start.clone().add(delta).project(camera),box=canvas.getBoundingClientRect();callout.hidden=end.z>1;callout.textContent=label;callout.style.left=Math.max(10,Math.min(box.width-260,(end.x*.5+.5)*box.width))+'px';callout.style.top=Math.max(180,Math.min(box.height-110,(-end.y*.5+.5)*box.height))+'px';
}

